const input = $input.first().json;
const body = input.body || input;
const harveyResponse = body.harvey_response || '';
const evidencePack = body.evidence_pack || {};
const sources = evidencePack.sources || [];
const allowedDomains = body.allowed_domains || ['boe.es', 'borme.es', 'oepm.es', 'euipo.europa.eu', 'wipo.int', 'registradores.org', 'consultas2.oepm.es'];

const issues = [];
let score = 100;

// Check 1: Citation validation — [SRC-XXX] must reference existing sources
const citationPattern = /\[SRC-(\d{3})\]/g;
const citations = [];
let match;
while ((match = citationPattern.exec(harveyResponse)) !== null) {
  citations.push(match[1]);
}
const uniqueCitations = [...new Set(citations)];
const sourceIds = sources.map((s, i) => String(i + 1).padStart(3, '0'));
const sourceIdSet = new Set(sourceIds);
// Also check for id field in sources
const sourceRefSet = new Set(sources.map(s => s.id ? s.id.replace('SRC-', '') : ''));
const validIds = new Set([...sourceIdSet, ...sourceRefSet]);

for (const cited of uniqueCitations) {
  if (!validIds.has(cited)) {
    issues.push({ type: 'invalid_citation', severity: 'error', detail: `[SRC-${cited}] does not match any source in evidence pack` });
    score -= 10;
  }
}

// Check 2: URL allowlist
const urlPattern = /https?:\/\/[^\s)"]+/g;
const urls = harveyResponse.match(urlPattern) || [];
for (const url of urls) {
  const domain = url.replace(/^https?:\/\//, '').split('/')[0];
  const isAllowed = allowedDomains.some(d => domain.endsWith(d));
  if (!isAllowed) {
    issues.push({ type: 'unauthorized_url', severity: 'warning', detail: `URL ${url} not in allowed domains` });
    score -= 3;
  }
}

// Check 3: Coverage — % of sources cited
const sourceCoverage = sources.length > 0 ? (uniqueCitations.length / sources.length) * 100 : 100;
if (sourceCoverage < 50) {
  issues.push({ type: 'low_coverage', severity: 'error', detail: `Only ${sourceCoverage.toFixed(0)}% of sources cited (target: >=95%)` });
  score -= 10;
} else if (sourceCoverage < 95) {
  issues.push({ type: 'moderate_coverage', severity: 'warning', detail: `${sourceCoverage.toFixed(0)}% of sources cited (target: >=95%)` });
  score -= 3;
}

// Check 4: No citation at all
if (uniqueCitations.length === 0 && sources.length > 0) {
  issues.push({ type: 'no_citations', severity: 'error', detail: 'Response contains zero citations but evidence pack has sources' });
  score -= 20;
}

score = Math.max(0, score);
const passed = score >= 80 && issues.filter(i => i.severity === 'error').length === 0;

return [{
  json: {
    passed,
    score,
    issues,
    stats: {
      total_citations: uniqueCitations.length,
      total_sources: sources.length,
      coverage_pct: sourceCoverage.toFixed(1),
      urls_checked: urls.length,
      errors: issues.filter(i => i.severity === 'error').length,
      warnings: issues.filter(i => i.severity === 'warning').length
    }
  }
}];
